BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "academic_academicperiod" (
	"id"	integer NOT NULL,
	"number"	smallint unsigned NOT NULL CHECK("number" >= 0),
	"name"	varchar(50) NOT NULL,
	"start_date"	date NOT NULL,
	"end_date"	date NOT NULL,
	"edit_deadline"	date NOT NULL,
	"academic_year"	varchar(9) NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "academic_administrator" (
	"id"	integer NOT NULL,
	"first_name"	varchar(100) NOT NULL,
	"middle_name"	varchar(100),
	"last_name"	varchar(100) NOT NULL,
	"second_last_name"	varchar(100),
	"title"	varchar(50) NOT NULL,
	"date_of_birth"	date,
	"email"	varchar(254) NOT NULL UNIQUE,
	"user_id"	bigint UNIQUE,
	"profile_picture"	varchar(100),
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("user_id") REFERENCES "authentication_user"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "academic_assignment" (
	"id"	integer NOT NULL,
	"name"	varchar(100) NOT NULL,
	"description"	text NOT NULL,
	"assignment_type"	varchar(20) NOT NULL,
	"date_assigned"	date NOT NULL,
	"due_date"	date,
	"weight"	real NOT NULL,
	"max_score"	decimal NOT NULL,
	"period"	smallint unsigned NOT NULL CHECK("period" >= 0),
	"year"	varchar(4) NOT NULL,
	"course_subject_id"	bigint NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("course_subject_id") REFERENCES "academic_coursesubject"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "academic_attendance" (
	"id"	integer NOT NULL,
	"date"	date NOT NULL,
	"present"	bool NOT NULL,
	"comments"	text NOT NULL,
	"student_id"	bigint NOT NULL,
	"subject_id"	bigint,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("student_id") REFERENCES "academic_student"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("subject_id") REFERENCES "academic_subject"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "academic_course" (
	"id"	integer NOT NULL,
	"name"	varchar(100) NOT NULL,
	"code"	varchar(20) NOT NULL UNIQUE,
	"academic_year"	varchar(9) NOT NULL,
	"description"	text NOT NULL,
	"grado_id"	bigint,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("grado_id") REFERENCES "academic_grado"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "academic_course_teachers" (
	"id"	integer NOT NULL,
	"course_id"	bigint NOT NULL,
	"teacher_id"	bigint NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("course_id") REFERENCES "academic_course"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("teacher_id") REFERENCES "academic_teacher"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "academic_coursesubject" (
	"id"	integer NOT NULL,
	"course_id"	bigint NOT NULL,
	"subject_id"	bigint NOT NULL,
	"teacher_id"	bigint,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("course_id") REFERENCES "academic_course"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("subject_id") REFERENCES "academic_subject"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("teacher_id") REFERENCES "academic_teacher"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "academic_grade" (
	"id"	integer NOT NULL,
	"value"	real NOT NULL,
	"date_assigned"	datetime NOT NULL,
	"period"	smallint unsigned NOT NULL CHECK("period" >= 0),
	"year"	varchar(4) NOT NULL,
	"comments"	text NOT NULL,
	"course_id"	bigint NOT NULL,
	"student_id"	bigint NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("course_id") REFERENCES "academic_course"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("student_id") REFERENCES "academic_student"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "academic_gradeentry" (
	"id"	integer NOT NULL,
	"score"	decimal NOT NULL,
	"grade_id"	bigint,
	"comments"	text NOT NULL,
	"late_submission"	bool NOT NULL,
	"student_id"	bigint,
	"submitted_date"	datetime,
	"assignment_id"	bigint,
	"created_at"	datetime NOT NULL,
	"updated_at"	datetime NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("assignment_id") REFERENCES "academic_assignment"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("grade_id") REFERENCES "academic_grade"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("student_id") REFERENCES "academic_student"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "academic_grado" (
	"id"	integer NOT NULL,
	"numero"	smallint unsigned NOT NULL CHECK("numero" >= 0) UNIQUE,
	"categoria"	varchar(20) NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "academic_student" (
	"id"	integer NOT NULL,
	"first_name"	varchar(100) NOT NULL,
	"middle_name"	varchar(100),
	"last_name"	varchar(100),
	"second_last_name"	varchar(100),
	"date_of_birth"	date NOT NULL,
	"email"	varchar(254) NOT NULL UNIQUE,
	"student_id"	varchar(20) NOT NULL UNIQUE,
	"photo"	varchar(100),
	"course_id"	bigint,
	"grado_id"	bigint,
	"user_id"	bigint UNIQUE,
	"gender"	varchar(10) NOT NULL,
	"neighborhood"	varchar(100) NOT NULL,
	"socioeconomic_status"	varchar(50) NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("course_id") REFERENCES "academic_course"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("grado_id") REFERENCES "academic_grado"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("user_id") REFERENCES "authentication_user"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "academic_subject" (
	"id"	integer NOT NULL,
	"name"	varchar(100) NOT NULL,
	"code"	varchar(20) NOT NULL UNIQUE,
	"grado_id"	bigint NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("grado_id") REFERENCES "academic_grado"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "academic_teacher" (
	"id"	integer NOT NULL,
	"first_name"	varchar(100) NOT NULL,
	"middle_name"	varchar(100),
	"last_name"	varchar(100) NOT NULL,
	"second_last_name"	varchar(100),
	"title"	varchar(50) NOT NULL,
	"date_of_birth"	date NOT NULL,
	"email"	varchar(254) NOT NULL UNIQUE,
	"specialization"	varchar(100) NOT NULL,
	"teacher_id"	varchar(20) NOT NULL UNIQUE,
	"user_id"	bigint UNIQUE,
	"profile_picture"	varchar(100),
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("user_id") REFERENCES "authentication_user"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "auth_group" (
	"id"	integer NOT NULL,
	"name"	varchar(150) NOT NULL UNIQUE,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" (
	"id"	integer NOT NULL,
	"group_id"	integer NOT NULL,
	"permission_id"	integer NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("group_id") REFERENCES "auth_group"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("permission_id") REFERENCES "auth_permission"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "auth_permission" (
	"id"	integer NOT NULL,
	"content_type_id"	integer NOT NULL,
	"codename"	varchar(100) NOT NULL,
	"name"	varchar(255) NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("content_type_id") REFERENCES "django_content_type"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "authentication_user" (
	"id"	integer NOT NULL,
	"password"	varchar(128) NOT NULL,
	"last_login"	datetime,
	"is_superuser"	bool NOT NULL,
	"first_name"	varchar(150) NOT NULL,
	"last_name"	varchar(150) NOT NULL,
	"is_staff"	bool NOT NULL,
	"is_active"	bool NOT NULL,
	"date_joined"	datetime NOT NULL,
	"email"	varchar(254) NOT NULL UNIQUE,
	"user_type"	varchar(20) NOT NULL,
	"profile_picture"	varchar(100),
	"middle_name"	varchar(100),
	"second_last_name"	varchar(100),
	"date_of_birth"	date,
	"email_confirmed"	bool NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "authentication_user_groups" (
	"id"	integer NOT NULL,
	"user_id"	bigint NOT NULL,
	"group_id"	integer NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("group_id") REFERENCES "auth_group"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("user_id") REFERENCES "authentication_user"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "authentication_user_user_permissions" (
	"id"	integer NOT NULL,
	"user_id"	bigint NOT NULL,
	"permission_id"	integer NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("permission_id") REFERENCES "auth_permission"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("user_id") REFERENCES "authentication_user"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "django_admin_log" (
	"id"	integer NOT NULL,
	"object_id"	text,
	"object_repr"	varchar(200) NOT NULL,
	"action_flag"	smallint unsigned NOT NULL CHECK("action_flag" >= 0),
	"change_message"	text NOT NULL,
	"content_type_id"	integer,
	"user_id"	bigint NOT NULL,
	"action_time"	datetime NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("content_type_id") REFERENCES "django_content_type"("id") DEFERRABLE INITIALLY DEFERRED,
	FOREIGN KEY("user_id") REFERENCES "authentication_user"("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS "django_content_type" (
	"id"	integer NOT NULL,
	"app_label"	varchar(100) NOT NULL,
	"model"	varchar(100) NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "django_migrations" (
	"id"	integer NOT NULL,
	"app"	varchar(255) NOT NULL,
	"name"	varchar(255) NOT NULL,
	"applied"	datetime NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "django_session" (
	"session_key"	varchar(40) NOT NULL,
	"session_data"	text NOT NULL,
	"expire_date"	datetime NOT NULL,
	PRIMARY KEY("session_key")
);
